			int year = 10000 + offset;
			String yearLabel = Integer.toString(year);
			String month = twoDigits((offset % 12) + 1);
			String day = twoDigits(offset + 1);
			String timezone = offset % 2 == 0 ? "Z" : "+14:00";
			String fraction = fraction(offset);
			String date = yearLabel + "-" + month + "-" + day;

			calendarValues.add(vf.createLiteral(yearLabel + timezone, XSD.GYEAR));
			calendarValues.add(vf.createLiteral(yearLabel + "-" + month + timezone, XSD.GYEARMONTH));
