	@Benchmark
	public int compareCalendarValues() {
		ValueComparator valueComparator = new ValueComparator();
		long checksum = 0;
		int position = 1;
		for (Value left : calendarValues) {
			for (Value right : calendarValues) {
				checksum = checksum * 31L + (long) valueComparator.compare(left, right) * position++;
			}
		}

		return (int) (checksum ^ (checksum >>> 32));
	}

	private static String twoDigits(int value) {
		return value < 10 ? "0" + value : Integer.toString(value);
	}

	private static String fraction(int offset) {
		return ".00000000" + (offset + 1);
	}

